import {
  DoubleSide,
  Material,
  MeshDepthMaterial,
  MeshStandardMaterial,
  type WebGLProgramParametersWithUniforms,
  type WebGLRenderer,
} from 'three';
import { getTexture } from './textures';
import { addWorldUniforms } from './world-shading';

/**
 * Shared material library. Assets reference materials by id so thousands of
 * instances / dozens of asset types share a handful of GPU programs.
 */
export type MaterialId =
  | 'vegetation'
  | 'foliage_card'
  | 'foliage_card_dry'
  | 'foliage_card_spring'
  | 'rock'
  | 'props'
  | 'chevron'
  | 'vehicle'
  | 'village_sign'
  | 'tree_impostor';

const cache = new Map<MaterialId, Material>();

/**
 * Wind sway (`RALLY_WIND`, metres of sway per m² of height) and leaf translucency (`RALLY_FOLIAGE`) for the
 * world shading (engine/world-shading.ts). Trees bend at the top, grass / reed cards at their tips.
 */
const TREE_DEFINES = { RALLY_WIND: 0.0009, RALLY_FOLIAGE: 0.3 };
const CARD_DEFINES = { RALLY_WIND: 0.1, RALLY_FOLIAGE: 0.25, RALLY_GROUND: 1 };

const FOLIAGE: MaterialId[] = [
  'foliage_card',
  'foliage_card_dry',
  'foliage_card_spring',
];
let foliageA2C = false;

/**
 * Grass / leaf cards: alpha-to-coverage when the renderer has MSAA (smooth, non-shimmering card edges at no cost;
 * three keeps the `alphaTest` cut and antialiases across it). Without MSAA it would do nothing: plain alpha test.
 * `createRenderer` calls this with the quality preset's `antialias`.
 */
export function setFoliageAntialias(on: boolean): void {
  foliageA2C = on;
  for (const id of FOLIAGE) {
    const m = cache.get(id);
    for (const x of m ? [m, variantMats.get(m)] : [])
      if (x && x.alphaToCoverage !== on) {
        x.alphaToCoverage = on;
        x.needsUpdate = true;
      }
  }
}

export function getMaterial(id: MaterialId): Material {
  let m = cache.get(id);
  if (m) return m;
  switch (id) {
    case 'vegetation':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('detail'),
        roughness: 0.92,
      });
      m.defines = { ...TREE_DEFINES };
      break;
    case 'foliage_card':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('grass_card'),
        alphaTest: 0.45,
        side: DoubleSide,
        roughness: 1,
      });
      break;
    case 'foliage_card_dry':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('grass_card_dry'),
        alphaTest: 0.45,
        side: DoubleSide,
        roughness: 1,
      });
      break;
    case 'foliage_card_spring':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('grass_card_spring'),
        alphaTest: 0.45,
        side: DoubleSide,
        roughness: 1,
      });
      break;
    case 'rock':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('rock'),
        bumpMap: getTexture('rock'),
        bumpScale: 2,
        roughness: 0.88,
      });
      break;
    case 'props':
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('detail'),
        roughness: 0.7,
      });
      break;
    case 'vehicle':
      // Vertex-coloured paint; the decals atlas supplies the lettering (plain faces sample its white corner).
      m = new MeshStandardMaterial({
        vertexColors: true,
        map: getTexture('vehicle_decals'),
        roughness: 0.42,
        metalness: 0.3,
      });
      break;
    case 'village_sign':
      m = new MeshStandardMaterial({
        map: getTexture('village_sign'),
        roughness: 0.55,
        side: DoubleSide,
      });
      break;
    case 'chevron':
      m = new MeshStandardMaterial({
        map: getTexture('chevron'),
        roughness: 0.55,
      });
      break;
    case 'tree_impostor':
      m = impostorMaterial();
      break;
  }
  m.name = id;
  if (FOLIAGE.includes(id)) {
    m.alphaToCoverage = foliageA2C;
    m.defines = { ...CARD_DEFINES };
  }
  cache.set(id, m);
  return m;
}

export function allMaterials(): Material[] {
  return [...cache.values()];
}

/**
 * Far trees (assets/impostor.ts): a flat diamond turned to face the camera in the vertex shader - 2 triangles
 * instead of an 8-face crown. Geometry x = sideways offset, y = height; the instance matrix places the axis.
 * Lit like a crown seen from the front (normal towards the camera, tipped up), no wind (sub-pixel).
 */
function impostorMaterial(): MeshStandardMaterial {
  const m = new MeshStandardMaterial({ vertexColors: true, roughness: 0.92 });
  m.defines = { RALLY_FOLIAGE: TREE_DEFINES.RALLY_FOLIAGE };
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    shader.vertexShader = shader.vertexShader
      .replace(
        '#include <defaultnormal_vertex>',
        '#include <defaultnormal_vertex>\ntransformedNormal = normalize( vec3( 0.0, 0.55, 1.0 ) );',
      )
      .replace(
        '#include <project_vertex>',
        `vec4 mvPosition = vec4( 0.0, transformed.y, 0.0, 1.0 );
#ifdef USE_INSTANCING
	mvPosition = instanceMatrix * mvPosition;
	float impostorScale = length( instanceMatrix[ 0 ].xyz );
#else
	float impostorScale = 1.0;
#endif
mvPosition = modelViewMatrix * mvPosition;
mvPosition.x += transformed.x * impostorScale;
gl_Position = projectionMatrix * mvPosition;`,
      );
  };
  m.customProgramCacheKey = () => 'tree-impostor-v1';
  return m;
}

/**
 * Variant sets (assets/library.ts `getVariantSet`): every variant of an asset in ONE geometry, each vertex tagged with
 * its `variantId`; the instance picks one with the per-instance `instVariant` attribute and the vertex shader clips
 * the other variants' triangles (all three corners to one point outside the clip volume). One draw per (asset, LOD,
 * material) instead of one per variant - the GPU runs the vertex shader over every variant, so keep sets small.
 */
const VARIANT_PARS = /* glsl */ `
attribute float variantId;
attribute float instVariant;`;
const VARIANT_CLIP = /* glsl */ `#include <project_vertex>
	if ( abs( variantId - instVariant ) > 0.5 ) gl_Position = vec4( 0.0, 0.0, 2.0, 1.0 );`;

function injectVariants(shader: WebGLProgramParametersWithUniforms): void {
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>${VARIANT_PARS}`)
    .replace('#include <project_vertex>', VARIANT_CLIP);
}

const variantMats = new Map<Material, Material>();
const variantDepth = new Map<Material, MeshDepthMaterial>();

/** `base` for variant-set meshes (cached; its own `onBeforeCompile`, or the world-shading default, runs first). */
export function variantMaterial(base: Material): Material {
  let m = variantMats.get(base);
  if (m) return m;
  m = base.clone();
  const baseHook = Object.prototype.hasOwnProperty.call(base, 'onBeforeCompile')
    ? base.onBeforeCompile
    : Material.prototype.onBeforeCompile;
  const baseKey = base.customProgramCacheKey();
  m.onBeforeCompile = (shader, renderer: WebGLRenderer) => {
    baseHook.call(base, shader, renderer);
    injectVariants(shader);
  };
  m.customProgramCacheKey = () => `${baseKey}|variants`;
  variantMats.set(base, m);
  return m;
}

/** Shadow-pass material for variant-set meshes of `base` (`customDepthMaterial`; three copies map / alphaTest onto it). */
export function variantDepthMaterial(base: Material): MeshDepthMaterial {
  let m = variantDepth.get(base);
  if (m) return m;
  m = new MeshDepthMaterial();
  m.onBeforeCompile = (shader) => injectVariants(shader);
  m.customProgramCacheKey = () => 'depth|variants';
  variantDepth.set(base, m);
  return m;
}
import {
  Color,
  Material,
  ShaderChunk,
  Vector3,
  Vector4,
  type Texture,
  type WebGLProgramParametersWithUniforms,
} from 'three';

/**
 * World shading shared by every material of the rally pages, installed once when this module is imported
 * (`engine/environment.ts` imports it):
 *
 * - **Cloud shadows:** the sun's direct light is dimmed under drifting clouds (world-space noise from the `macro`
 *   texture, projected along the sun onto a cloud layer). Every lit material (standard / physical / lambert).
 * - **Canopy shadows:** ground materials (`defines.RALLY_GROUND`: terrain, roads, grass cards) lose the sun under a
 *   baked top-down tree-shadow texture (world/canopy-shadows.ts) - only outside the sun's shadow-map box, which
 *   already draws the real tree shadows near the car.
 * - **Height fog + sun glow:** `FogExp2` whose density falls off with height above the focus point (valleys hazier,
 *   hill tops and aerial views clearer) and a fog colour that warms towards the sun. Every material with `fog`
 *   (incl. the dust).
 * - **Wind:** vertex sway for materials with `defines.RALLY_WIND` (= sway per metre² of height above the asset
 *   origin; foliage materials in `engine/materials.ts`), phase from the instance position.
 * - **Leaf translucency:** materials with `defines.RALLY_FOLIAGE` glow a little when the sun is behind them.
 *
 * How: ShaderChunk overrides (fog, begin_vertex, lights) that read the `ws*` uniforms below, and a default
 * `Material.onBeforeCompile` that hands those uniforms (shared objects) to every program. Materials with their own
 * `onBeforeCompile` (terrain, lamps) call `addWorldUniforms(shader)`; ShaderMaterials (dust) merge `worldUniforms`
 * and include `WORLD_SHADING_DECL`. A program that never gets the uniforms reads 0 = everything off, i.e. plain
 * three.js shading - so pages that never call `setWorldShading` look exactly as before.
 */

/** Shared uniform objects (same references in every program). */
export const worldUniforms = {
  wsTime: { value: 0 },
  wsSunDir: { value: new Vector3(0, 1, 0) },
  /** x strength (0 = off), y coverage 0..1, z noise frequency (1/m), w cloud layer height above the ground (m). */
  wsCloud: { value: new Vector4(0, 0.4, 1 / 1000, 1200) },
  /** xy cloud drift (m/s), z foliage sway strength (0 = still), w sway frequency (rad/s). */
  wsWind: { value: new Vector4(4.2, 4.2, 0, 1.3) },
  /** xyz sun glow added to the fog colour towards the sun (linear, 0 = off), w height falloff (1/m, 0 = off). */
  wsFog: { value: new Vector4(0, 0, 0, 0) },
  /** Height (m) where the fog has the map's `fogDensity`: the focus point (car / orbit target), `setFogBase`. */
  wsFogBase: { value: 0 },
  wsMacro: { value: null as Texture | null },
  /** Canopy shadow texture (world/canopy-shadows.ts) and its ground mapping: x0, z0, 1/width, 1/depth. */
  wsCanopy: { value: null as Texture | null },
  wsCanopyMap: { value: new Vector4(0, 0, 0, 0) },
  /** Shadow-map box on the ground: centre x, z, half extent (m), canopy shadow strength (0 = off). */
  wsShadowBox: { value: new Vector4(0, 0, 60, 0) },
};
// Dev: tweak live from the console (`__worldShading.wsCloud.value.x = 1`).
(globalThis as { __worldShading?: typeof worldUniforms }).__worldShading =
  worldUniforms;

/** Give a program the world uniforms (for materials that replace `onBeforeCompile`). */
export function addWorldUniforms(
  shader: WebGLProgramParametersWithUniforms,
): void {
  Object.assign(shader.uniforms, worldUniforms);
}

export interface WorldShadingSettings {
  sunDir: Vector3;
  sunColor: Color;
  /** 0..1 how dark cloud shadows get (0 = off). */
  cloudShadow: number;
  cloudCoverage: number;
  /** Cloud drift speed multiplier. */
  cloudSpeed: number;
  /** Foliage sway multiplier (0 = still). */
  wind: number;
  /** Fog sun glow (multiplies the sun colour, 0 = off). */
  fogSunGlow: number;
  /** Fog height falloff (1/m, 0 = flat fog). */
  fogFalloff: number;
  macro: Texture;
}

export function setWorldShading(s: WorldShadingSettings): void {
  const u = worldUniforms;
  u.wsSunDir.value.copy(s.sunDir).normalize();
  u.wsCloud.value.x = s.cloudShadow;
  u.wsCloud.value.y = s.cloudCoverage;
  u.wsWind.value.x = 4.2 * s.cloudSpeed;
  u.wsWind.value.y = 2.4 * s.cloudSpeed;
  u.wsWind.value.z = s.wind;
  const glow = s.fogSunGlow;
  u.wsFog.value.set(
    s.sunColor.r * glow,
    s.sunColor.g * glow,
    s.sunColor.b * glow,
    s.fogFalloff,
  );
