          const sn = Math.sin(o.rot ?? 0);
          const dx = c.x - o.x;
          const dz = c.z - o.z;
          const lx = dx * cs - dz * sn;
          const lz = dx * sn + dz * cs;
          const bx = o.hx ?? 0;
          const bz = o.hz ?? 0;
          const ex = lx - Math.max(-bx, Math.min(bx, lx));
