constructor(readonly map: MapDef) {
  this.gen = new TerrainGenerator(map);
  this.road = this.gen.road;
  this.heightfield = new Heightfield(this.gen);
  this.analytic = new AnalyticTerrain(this.gen);
  this.landmarks = landmarksOf(map);
  const rails = this.gen.railPaths();
  this.buildings = new BuildingIndex(
    (map.buildings ?? []).filter(
      (b) =>
        !this.landmarks.some((l) => l.replaces(b)) &&
        !(rails.length && this.onTrackBed(b)),
    ),
  );
  const b = map.bounds;
  const m = RENDER_MARGIN * 0.6;
  this.scatter = new ScatterField(
    this.analytic,
    this.road,
    map.seed,
    map.scatter,
    (x, z) =>
      x > b.minX - m && x < b.maxX + m && z > b.minZ - m && z < b.maxZ + m,
    (x, z) =>
      map.terrain.flatAreas.some(
        (f) => Math.hypot(x - f.x, z - f.z) < f.radius + 4,
      ) ||
      this.buildings.contains(x, z, 1.5) ||
      this.landmarks.some((l) => l.occupies(x, z, 1.5)) ||
      // No trees hanging into an underpass trench.
      this.gen.inUnderpassTrench(x, z),
    this.heightfield,
    {
      landcover: this.gen.landcover,
      paths: this.gen.paths,
      channels: this.gen.channels,
      lakes: this.gen.lakes,
    },
  );
  const crowdQ = newPathQuery();
  const fanQ = newPathQuery();
  const fanLq = newLakeQuery();
  this.cornerFans = map.cornerFans
    ? cornerFanInstances(
        this.road,
        (x, z) => this.analytic.height(x, z),
        map.cornerFans,
        map.seed,
        this.gen.junctions,
        (x, z) =>
          map.terrain.flatAreas.some(
            (f) => Math.hypot(x - f.x, z - f.z) < f.radius + 4,
          ) ||
          this.buildings.contains(x, z, 1) ||
          this.landmarks.some((l) => l.occupies(x, z, 1)) ||
          (!!this.gen.paths?.query(x, z, fanQ).found &&
            fanQ.distance < fanQ.halfWidth + 1) ||
          (!!this.gen.channels?.query(x, z, fanQ).found &&
            fanQ.distance < fanQ.halfWidth + 3) ||
          (!!this.gen.lakes?.query(x, z, fanLq) && fanLq.sd < 3),
      )
    : [];
  for (const inst of [
    ...roadsideInstances(
      this.road,
      this.analytic,
      map.roadside,
      map.seed,
      this.gen.junctions,
      this.gen.paths,
    ),
    ...this.cornerFans,
  ]) {
    // A lamp post in a portal would stand up through the slab (the portal has its own strip lights).
    if (
      inst.asset === 'street_lamp' &&
      this.gen.portals.inside(inst.x, inst.z)
    )
      continue;
    // No crowd standing in a house (a crowd spot in a village).
    if (
      inst.asset === 'spectator' &&
      this.buildings.contains(inst.x, inst.z, 0.5)
    )
      continue;
    // No crowd standing on another carriageway / parkway lane beside the stage road.
    if (inst.asset === 'spectator' && this.gen.paths) {
      const q = this.gen.paths.query(inst.x, inst.z, crowdQ, 'tarmac', (pi) =>
        this.gen.isCarriageway(pi),
      );
      if (q.found && q.distance <= q.halfWidth + 0.5) continue;
    }
    this.scatter.addFixed(inst);
  }
  for (const inst of this.propInstances()) this.scatter.addFixed(inst);
  const bq = newPathQuery();
  const ba = { x: 0, z: 0 };
  const bb = { x: 0, z: 0 };
  const lanesNet = this.gen.paths;
  this.laneWalls = lanesNet

