    {
      pred: 'A(k)',
      cond: 'k < 6',
      succ:
        '[&(rnd(10,34))!B(rnd(0.4,0.55),0)]>(rnd(50,95))[&(rnd(18,40))!B(rnd(0.35,0.5),0)]>(rnd(60,100))A(k+1)',
