/** The symbols the turtle reads (trees/skeleton.ts). */
export const ALPHABET = 'FfAB+-&^<>|![]L';

export interface Module {
  s: string;
  a: number[];
}

interface Env {
  v: Record<string, number>;
  rng: TreeRng;
}
type Expr = (env: Env) => number;

// --- expressions ---------------------------------------------------------------------------------------------

const TOKEN = /\s*(\d+\.?\d*(?:[eE][-+]?\d+)?|\.\d+|[A-Za-z_]\w*|<=|>=|==|!=|&&|\|\||[-+*/(),<>])/y;

function tokenize(src: string): string[] {
  const out: string[] = [];
  TOKEN.lastIndex = 0;
  while (TOKEN.lastIndex < src.length) {
    if (/^\s*$/.test(src.slice(TOKEN.lastIndex))) break;
    const m = TOKEN.exec(src);
    if (!m) throw new Error(`Tree grammar: bad expression "${src}"`);
    out.push(m[1]);
  }
  return out;
}

const BINARY: Record<string, [number, (a: number, b: number) => number]> = {
  '||': [1, (a, b) => (a || b ? 1 : 0)],
  '&&': [2, (a, b) => (a && b ? 1 : 0)],
  '==': [3, (a, b) => (a === b ? 1 : 0)],
  '!=': [3, (a, b) => (a !== b ? 1 : 0)],
  '<': [4, (a, b) => (a < b ? 1 : 0)],
  '>': [4, (a, b) => (a > b ? 1 : 0)],
  '<=': [4, (a, b) => (a <= b ? 1 : 0)],
  '>=': [4, (a, b) => (a >= b ? 1 : 0)],
  '+': [5, (a, b) => a + b],
  '-': [5, (a, b) => a - b],
  '*': [6, (a, b) => a * b],
  '/': [6, (a, b) => a / b],
};

const FUNCTIONS: Record<string, (env: Env, args: number[]) => number> = {
  /** Parameter jitter: uniform in [a, b) from the tree's PRNG. */
  rnd: (env, [a, b]) => env.rng.range(a, b),
  min: (_e, [a, b]) => Math.min(a, b),
  max: (_e, [a, b]) => Math.max(a, b),
};

/** Arithmetic / comparison expression -> closure (no eval). */
export function compileExpr(src: string): Expr {
  const t = tokenize(src);
  let i = 0;
  const peek = () => t[i];
  const expect = (s: string) => {
    if (t[i++] !== s) throw new Error(`Tree grammar: expected "${s}" in "${src}"`);
  };
  const primary = (): Expr => {
    const tok = t[i++];
    if (tok === undefined) throw new Error(`Tree grammar: unexpected end of "${src}"`);
    if (tok === '(') {
      const e = binary(0);
      expect(')');
      return e;
    }
    if (tok === '-') {
      const e = primary();
      return (env) => -e(env);
    }
    if (/^[\d.]/.test(tok)) {
      const n = Number(tok);
      return () => n;
    }
    if (peek() === '(') {
      const f = FUNCTIONS[tok];
      if (!f) throw new Error(`Tree grammar: unknown function "${tok}" in "${src}"`);
