import { derive } from './grammar';
import { mix32, type V3 } from './math';
import { buildMeshes, type Crown, type VariantMeshes } from './mesh';
import { buildSkeleton, type Skeleton } from './skeleton';
import {
  getSpecies,
  speciesHash,
  variantCount,
  type SpeciesDef,
} from './species';

/**
 * A species' variant pool (spec: trees/Placement.md#variants): each variant grows from its own seed through
 * grammar -> skeleton -> meshing. `generateVariant` is pure (the worker runs it, tests and tools call it directly);
 * the registry holds the summaries placement and drawing read, filled when a stage loads (trees/load.ts).
 */

/** Bump when generated output changes for the same species and seed: cached variants regenerate. */
export const GENERATOR_VERSION = 1;

export interface TreeVariantInfo {
  species: string;
  index: number;
  seed: number;
  /** Cache key: species hash, variant seed, generator version. */
  key: string;
  height: number;
  radius: number;
  sphere: { cy: number; r: number };
  crown: Crown;
  foliageColor: V3;
  /** Collision capsules (object space), 7 floats each: ax ay az bx by bz radius. */
  capsules: Float32Array;
}

export interface GeneratedVariant {
  info: TreeVariantInfo;
  meshes: VariantMeshes;
}

/** Seed of a species' variant: from the species content hash, so any change to the species gives new variants. */
export function variantSeed(def: SpeciesDef, index: number): number {
  return mix32(speciesHash(def), index + 1);
}

export function cacheKey(def: SpeciesDef, seed: number): string {
  return `${def.name}:${speciesHash(def).toString(16)}:${seed.toString(16)}:v${GENERATOR_VERSION}`;
}

/** Trunk and first-order limb segments at least `collisionRadius` thick, as capsules (trees/Placement.md#collision). */
export function skeletonCapsules(sk: Skeleton, def: SpeciesDef): Float32Array {
  const out: number[] = [];
  for (const s of sk.segments) {
    if (s.order > 1 || s.r0 < def.collisionRadius) continue;
    out.push(...s.start, ...s.end, s.r0);
  }
  return new Float32Array(out);
}

export function generateVariant(def: SpeciesDef, index: number): GeneratedVariant {
  const seed = variantSeed(def, index);
  const sk = buildSkeleton(derive(def, seed), def);
  const meshes = buildMeshes(sk, def, seed);
  return {
    info: {
      species: def.name,
      index,
      seed,
      key: cacheKey(def, seed),
      height: meshes.height,
      radius: meshes.radius,
      sphere: meshes.sphere,
      crown: meshes.crown,
      foliageColor: meshes.foliageColor,
      capsules: skeletonCapsules(sk, def),
    },
    meshes,
  };
}

const registry = new Map<string, TreeVariantInfo>();

export function registerVariant(info: TreeVariantInfo): void {
  registry.set(`${info.species}#${info.index}`, info);
}

/**
 * A variant's summary: registered at stage load; generated on the spot where nothing loaded them (node tests,
 * tools), which is the same deterministic result.
 */
export function variantInfo(species: string, index: number): TreeVariantInfo {
  const key = `${species}#${index}`;
  let info = registry.get(key);
  if (!info) {
    info = generateVariant(getSpecies(species), index).info;
    registry.set(key, info);
  }
  return info;
}

export function variantsOf(def: SpeciesDef): number[] {
  return [...Array(variantCount(def)).keys()];
}

import type { StaticCollider } from '../physics/types';
import { hashText, mix32, unit, type V3 } from './math';
import { isTreeType, speciesOfType, variantCount } from './species';
import { variantInfo } from './variants';

/**
 * Stage 5, placement (spec: trees/Placement.md): trees stand where the stage data puts its tree types (scatter /
 * roadside / props rules); each placed tree is posed by a hash of the stage id and its placement index, so a stage
 * always grows the same forest. Pure (world / physics side, runs in node).
 */

/** What a placed tree takes from its hash, besides variant / rotation / scale. */
export interface TreePose {
  species: string;
  /** Hue shift (fraction of a turn) and value multiplier within the species palette. */
  hue: number;
  value: number;
  /** Wind phase offset of the whole tree (rad). */
  phase: number;
}

export interface PlacedTree {
  variant: number;
  rotY: number;
  scale: number;
  pose: TreePose;
}

/** Pose of the `index`-th tree placed on stage `stageId`, a tree type from the map data. */
export function placeTree(stageId: string, index: number, asset: string): PlacedTree {
  const def = speciesOfType(asset);
  const h = mix32(hashText(stageId), index);
  const u = (k: number) => unit(mix32(h, k));
  return {
    variant: Math.min(variantCount(def) - 1, Math.floor(u(1) * variantCount(def))),
    rotY: u(2) * Math.PI * 2,
    scale: def.scale[0] + (def.scale[1] - def.scale[0]) * u(3),
    pose: {
      species: def.name,
      hue: (u(4) - 0.5) * 0.06,
      value: 0.86 + 0.26 * u(5),
      phase: u(6) * Math.PI * 2,
    },
  };
}

interface Placed {
  asset: string;
  variant: number;
  x: number;
  y: number;
  z: number;
  rotY: number;
  scale: number;
}

/** World-space collision capsules of a placed tree (the same whichever level is drawn). */
export function treeColliders(inst: Placed): StaticCollider[] {
  const def = speciesOfType(inst.asset);
  const caps = variantInfo(def.name, inst.variant).capsules;
  const c = Math.cos(inst.rotY);
  const s = Math.sin(inst.rotY);
  const k = inst.scale;
  const out: StaticCollider[] = [];
  const at = (i: number): V3 => {
    const x = caps[i] * k;
    const z = caps[i + 2] * k;
    return [inst.x + x * c + z * s, inst.y + caps[i + 1] * k, inst.z - x * s + z * c];
  };
  for (let i = 0; i < caps.length; i += 7) {
    const a = at(i);
    const b = at(i + 3);
    const rc = caps[i + 6] * k;
    out.push({
      kind: 'capsule',
      x: (a[0] + b[0]) / 2,
      z: (a[2] + b[2]) / 2,
      y: Math.min(a[1], b[1]) - rc,
      h: Math.abs(b[1] - a[1]) + rc * 2,
      r: Math.sqrt((b[0] - a[0]) ** 2 + (b[2] - a[2]) ** 2) / 2 + rc,
      a,
      b,
      rc,
    });
  }
  return out;
}

/** A tree type's crown seen from above at scale 1 (aerial previews, baked canopy shadows): variant 0's crown. */
export function treeCanopy(asset: string): { radius: number; height: number; color: V3 } {
  const info = variantInfo(speciesOfType(asset).name, 0);
  const f = info.foliageColor;
  return {
    radius: info.crown.r[0] * 0.85,
    height: info.crown.c[1],
    color: [f[0] * 0.75, f[1] * 0.75, f[2] * 0.75],
  };
}

export { isTreeType };

