 * ~85k circles over the whole map) - the skipped instances are never generated;
 * rocks (not drawn up there) are dropped. `grow` = tree circle radius factor so
 * woods still cover the same ground.
 */
function previewMap(map: MapDef): { map: MapDef; grow: number } {
  const b = map.bounds;
  const k = Math.min(
    1,
    LARGE_MAP_AREA / ((b.maxX - b.minX) * (b.maxZ - b.minZ)),
  );
  const scatter = map.scatter
    .filter((r) => !r.detail && getAssetMeta(r.asset).category !== 'rocks')
    .map((r) => ({
      ...r,
      density: r.density * k,
      rows: r.rows && { ...r.rows, keep: (r.rows.keep ?? 0.93) * k },
    }));
  return { map: { ...map, scatter }, grow: Math.min(3, 1 / Math.sqrt(k)) };
}

/**
  ) {
    disc ??= new CircleGeometry(1, 10).rotateX(-Math.PI / 2);
    this.mesh = new InstancedMesh(disc, this.material, 0);
    this.mesh.name = 'aerial trees';
    this.mesh.frustumCulled = false;
  }

  /** Collects every vegetation instance on the map; yields after each chunk. */
  *job(): Generator<void> {
    const scatter = this.world.scatter;
    const cs = scatter.chunkSize;
    const b = this.world.map.bounds;
    const mats: number[] = [];
    const cols: number[] = [];
    const tint = new Color();
    for (
      let cz = Math.floor((b.minZ - 300) / cs);
      cz * cs <= b.maxZ + 300;
      cz++
    ) {
      for (
        let cx = Math.floor((b.minX - 300) / cs);
        cx * cs <= b.maxX + 300;
        cx++
      ) {
        for (const inst of scatter.chunk(cx, cz).instances) {
          if (getAssetMeta(inst.asset).category !== 'vegetation') continue;
          const c = canopyOf(inst.asset);
          const r = c.radius * inst.scale * this.grow;
          // Column-major matrix: scale (r, 1, r), translate to canopy height.
          mats.push(r, 0, 0, 0, 0, 1, 0, 0, 0, 0, r, 0);
          mats.push(inst.x, inst.y + c.height * inst.scale, inst.z, 1);
          const j =
            0.88 +
            (hash3(Math.floor(inst.x * 7), Math.floor(inst.z * 7), 9) /
              4294967296) *
              0.24;
          tint.copy(c.color).multiplyScalar(j);
          cols.push(tint.r, tint.g, tint.b);
        }
        yield;
      }
    }
    // Fill the (empty until now) mesh in one go.
    this.mesh.instanceMatrix = new InstancedBufferAttribute(
      new Float32Array(mats),
      16,
    );
    this.mesh.instanceColor = new InstancedBufferAttribute(
      new Float32Array(cols),
      3,
    );
    this.mesh.count = cols.length / 3;
  }

  dispose(): void {
        this.cursor++;
        continue;
      }
      for (const inst of chunk.instances) this.splat(inst);
      // Swap-remove: the last pending key takes this slot (looked at next).
      this.todoCount--;
      this.todo[i] = this.todo[this.todoCount * 2];
      this.todo[i + 1] = this.todo[this.todoCount * 2 + 1];
    }
    if (this.dirtyMin >= 0 && now - this.lastUpload >= UPLOAD_EVERY) {
      const a = this.dirtyMin * this.nx;
      const b = (this.dirtyMax + 1) * this.nx;
      for (let k = a; k < b; k++) this.data[k] = Math.round(this.grid[k] * 255);
      this.texture.needsUpdate = true;
      this.dirtyMin = this.dirtyMax = -1;
      this.lastUpload = now;
    }
  }

  private splat(inst: ScatterInstance): void {
    if (getAssetMeta(inst.asset).category !== 'vegetation') return;
    const c = canopyOf(inst.asset);
    const r = c.radius * inst.scale;
    // Skip bushes / grass: small shadows are lost at 3 m texels anyway.
    if (r < 0.9) return;
    const { nx, nz, res, grid } = this;
    const { x0, z0 } = this.map;
    const h = c.height * inst.scale;
    const sx = inst.x + this.ox * h;
    const sz = inst.z + this.oz * h;
    const ra = r * this.stretch; // along the sun azimuth
    const reach = ra + res;
    const i0 = Math.max(0, Math.floor((sx - reach - x0) / res));
    const i1 = Math.min(nx - 1, Math.ceil((sx + reach - x0) / res));
    const j0 = Math.max(0, Math.floor((sz - reach - z0) / res));
    const j1 = Math.min(nz - 1, Math.ceil((sz + reach - z0) / res));
    if (i0 > i1 || j0 > j1) return;
    for (let j = j0; j <= j1; j++) {
      const pz = z0 + (j + 0.5) * res - sz;
      for (let i = i0; i <= i1; i++) {
        const px = x0 + (i + 0.5) * res - sx;
        // Ellipse coordinates: along / across the sun azimuth.
        const u = (px * this.ax + pz * this.az) / ra;
        const v = (-px * this.az + pz * this.ax) / r;
        const q = u * u + v * v;
        if (q >= 1) continue;
        const k = j * nx + i;
        grid[k] = Math.min(1, grid[k] + DENSITY * (1 - q) * (1 - q));
      }
    }
    this.dirtyMin = this.dirtyMin < 0 ? j0 : Math.min(this.dirtyMin, j0);
    this.dirtyMax = Math.max(this.dirtyMax, j1);
  }

  dispose(): void {
    this.texture.dispose();

