      const low = cs.reduce((m, c) => (c.y < m.y ? c : m));
      expect(low.kind).toBe('capsule');
      expect(Math.hypot(low.a![0] - 10, low.a![2] + 5)).toBeLessThan(0.01);
      expect(low.a![1]).toBeCloseTo(2, 5);
    }
    expect(at('bush')).toEqual([]);
  });
});

