import {
  DataTexture,
  DoubleSide,
  LinearFilter,
  LinearMipmapLinearFilter,
  MeshDepthMaterial,
  MeshStandardMaterial,
  RepeatWrapping,
  RGBADepthPacking,
  SRGBColorSpace,
  Vector2,
  Vector3,
  type Texture,
  type WebGLProgramParametersWithUniforms,
} from 'three';
import { addWorldUniforms } from '../engine/world-shading';
import { mix32, unit } from './math';
import type { BarkTexture, FoliageKind } from './species';

/**
 * Shared materials of the tree module (used by the impostor bake and the drawing stage): procedural bark and leaf
 * textures, and the tree shader code injected into three's standard / depth materials:
 *
 * - **Level cross-fade** (trees/Lod.md#transition): every instance carries `treeLod` = (Tprev, band, Tnext, band),
 *   the screen-height thresholds (px at 1080 px) to the finer and the coarser level, and `treeShadow` the same for
 *   the shadow pass (one level coarser, trees/draw.ts). The vertex shader measures the tree's projected height from
 *   the main camera (`tlCam`, `tlPx`), the fragment shader keeps the pixels whose screen-fixed dither value lies in
 *   [pNext, pPrev): a finer level fading out keeps d >= p, the coarser one fading in keeps d < p, so together they
 *   cover each pixel once. Fully faded instances collapse in the vertex shader.
 * - **Wind** (trees/Foliage.md#wind): the trunk bends with height^2, each limb sways about the trunk with its own
 *   phase and an amplitude growing with branch order and distance along the limb (`treeWind`), leaves flutter. The
 *   impostor applies the trunk term only.
 * - **Colour** (trees/Foliage.md#shading): per-instance hue / value (`treeInst`), baked ambient occlusion, leaf
 *   normals blended with the crown (in the mesh data) and kept unflipped on back faces, translucency
 *   (`RALLY_FOLIAGE`, engine/world-shading.ts).
 */

/** Main camera for the level choice (also in the shadow pass): position and px per (m / m) at 1080 px. */
export const treeUniforms = {
  tlCam: { value: new Vector3() },
  tlPx: { value: 650 },
};

/** Reference view height the thresholds are given for (px). */
export const REFERENCE_HEIGHT = 1080;

// --- GLSL ------------------------------------------------------------------------------------------------------

const VERTEX_PARS = /* glsl */ `
uniform vec3 tlCam;
uniform float tlPx;
attribute vec4 treeInst;
attribute vec4 treeLod;
attribute vec4 treeShadow;
#ifndef TREE_IMPOSTOR
attribute vec4 treeWind;
#endif
varying vec2 vTreeKeep;
varying vec2 vTreeTint;
varying float vTreeAO;
/** Visible dither range [pNext, pPrev) of a level at projected height h. */
vec2 treeKeep( vec4 lod, float h ) {
	float pPrev = lod.x > 0.0 ? clamp( ( lod.x - h ) / ( lod.x * lod.y ), 0.0, 1.0 ) : ( lod.x < 0.0 ? 0.0 : 1.0 );
	float pNext = lod.z > 0.0 ? clamp( ( lod.z - h ) / ( lod.z * lod.w ), 0.0, 1.0 ) : 0.0;
	return vec2( pNext, pPrev );
}
/** Trunk sway (object space metres along the wind) at height y of a tree of height H. */
float treeTrunk( float y, float phase, float gust ) {
	float hy = max( y, 0.0 );
	return 0.0009 * hy * hy * gust * ( sin( wsTime * 0.9 + phase ) + 0.3 * sin( wsTime * 2.1 + phase * 1.7 ) );
}
`;

/** After begin_vertex: wind, then the level visibility. */
const VERTEX_MAIN = /* glsl */ `
	vec3 tOrigin = ( modelMatrix * instanceMatrix * vec4( 0.0, 0.0, 0.0, 1.0 ) ).xyz;
	float tScale = length( instanceMatrix[ 0 ].xyz );
	mat3 tRot = mat3( instanceMatrix ) / tScale;
	vec3 tWindW = vec3( wsWind.x, 0.0, wsWind.y );
	tWindW = dot( tWindW, tWindW ) > 1e-6 ? normalize( tWindW ) : vec3( 1.0, 0.0, 0.0 );
	vec3 tWind = transpose( tRot ) * tWindW;
	float tGust = wsWind.z * ( 0.65 + 0.35 * sin( wsTime * 0.31 + treeInst.z * 0.5 + dot( tOrigin.xz, vec2( 0.011, 0.007 ) ) ) );
	#ifdef TREE_IMPOSTOR
		transformed += tWind * treeTrunk( transformed.y, treeInst.z, tGust );
	#else
		transformed += tWind * treeTrunk( position.y, treeInst.z, tGust );
		// Limbs sway about the trunk (phase per limb), more for higher orders and further out along the limb.
		float tBranch = 0.012 * tGust * ( 1.0 + 0.35 * treeWind.x ) * treeWind.z * sin( wsTime * 1.7 + treeWind.y + treeInst.z );
		transformed += ( tWind + vec3( 0.0, 0.3, 0.0 ) ) * tBranch;
		#ifdef TREE_LEAF
			float tFlutter = 0.025 * wsWind.z * uv.y * sin( wsTime * 7.3 + treeWind.y * 3.1 + dot( position, vec3( 2.1, 1.7, 2.9 ) ) );
			transformed += normal * tFlutter;
		#endif
	#endif
	float tDist = max( distance( tOrigin + vec3( 0.0, treeInst.w * 0.5, 0.0 ), tlCam ), 0.5 );
	float tH = treeInst.w * tlPx / tDist;
	#ifdef TREE_SHADOW_PASS
		vTreeKeep = treeKeep( treeShadow, tH );
	#else
		vTreeKeep = treeKeep( treeLod, tH );
	#endif
	vTreeTint = treeInst.xy;
	#ifdef TREE_IMPOSTOR
		vTreeAO = 1.0;
	#else
		vTreeAO = treeWind.w;
	#endif
`;

const VERTEX_COLLAPSE = /* glsl */ `
	if ( vTreeKeep.x >= vTreeKeep.y ) gl_Position = vec4( 0.0, 0.0, 2.0, 1.0 );
`;

const FRAGMENT_PARS = /* glsl */ `
varying vec2 vTreeKeep;
varying vec2 vTreeTint;
varying float vTreeAO;
/** Screen-fixed dither 0..1 (interleaved gradient noise): stable on screen, does not crawl with the camera. */
float treeDither() {
	return fract( 52.9829189 * fract( dot( floor( gl_FragCoord.xy ), vec2( 0.06711056, 0.00583715 ) ) ) );
}
vec3 treeHue( vec3 c, float turn ) {
	const mat3 toYIQ = mat3( 0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312 );
	const mat3 toRGB = mat3( 1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703 );
	vec3 yiq = toYIQ * c;
	float a = turn * 6.2831853;
	yiq.yz = mat2( cos( a ), sin( a ), -sin( a ), cos( a ) ) * yiq.yz;
	return max( toRGB * yiq, 0.0 );
}
`;

const FRAGMENT_DITHER = /* glsl */ `
	float tD = treeDither();
	if ( tD < vTreeKeep.x || tD >= vTreeKeep.y ) discard;
`;

const FRAGMENT_COLOR = /* glsl */ `
	diffuseColor.rgb = treeHue( diffuseColor.rgb, vTreeTint.x ) * vTreeTint.y * mix( 0.65, 1.0, vTreeAO );
`;

function injectVertex(shader: WebGLProgramParametersWithUniforms, project: boolean): void {
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', `#include <common>\n${VERTEX_PARS}`)
    .replace('#include <begin_vertex>', `#include <begin_vertex>\n${VERTEX_MAIN}`);
  if (project)
    shader.vertexShader = shader.vertexShader.replace(
      '#include <project_vertex>',
      `#include <project_vertex>\n${VERTEX_COLLAPSE}`,
    );
}

function injectFragment(shader: WebGLProgramParametersWithUniforms): void {
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>', `#include <common>\n${FRAGMENT_PARS}`)
    .replace('void main() {', `void main() {\n${FRAGMENT_DITHER}`);
}

function hookStandard(m: MeshStandardMaterial, key: string, leaf: boolean): void {
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    Object.assign(shader.uniforms, treeUniforms);
    injectVertex(shader, true);
    injectFragment(shader);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <color_fragment>', `#include <color_fragment>\n${FRAGMENT_COLOR}`)
      .replace(
        '#include <lights_fragment_end>',
        '#include <lights_fragment_end>\n\treflectedLight.indirectDiffuse *= vTreeAO;',
      );
    // Leaves: the crown-blended normal faces out on both sides of the card (no back-face flip).
    if (leaf)
      shader.fragmentShader = shader.fragmentShader.replace(
        '#include <normal_fragment_begin>',
        '#include <normal_fragment_begin>\n\tnormal = normalize( vNormal );',
      );
  };
  m.customProgramCacheKey = () => key;
}

// --- textures --------------------------------------------------------------------------------------------------

function noise2(x: number, y: number, seed: number, wrapX: number, wrapY: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const fx = x - xi;
  const fy = y - yi;
  const h = (i: number, j: number) =>
    unit(mix32(mix32(seed, ((xi + i) % wrapX + wrapX) % wrapX), ((yi + j) % wrapY + wrapY) % wrapY));
  const sx = fx * fx * (3 - 2 * fx);
  const sy = fy * fy * (3 - 2 * fy);
  const a = h(0, 0) + (h(1, 0) - h(0, 0)) * sx;
  const b = h(0, 1) + (h(1, 1) - h(0, 1)) * sx;
  return a + (b - a) * sy;
}

const textures = new Map<string, Texture>();

/** Grey bark detail (multiplies the bark vertex colour): u around the branch, v along it. */
export function barkTexture(kind: BarkTexture): Texture {
  let t = textures.get(`bark:${kind}`);
  if (t) return t;
  const w = 64;
  const h = 128;
  const data = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      let v: number;
      if (kind === 'furrowed') {
        // Vertical plates split by dark furrows.
        const ridge = noise2(x / 6, y / 24, 11, w / 6, h / 24);
        const plate = noise2(x / 3, y / 6, 12, w / 3, h / 6);
        v = 0.45 + 0.55 * Math.pow(Math.abs(ridge * 2 - 1), 0.6) * (0.75 + 0.25 * plate);
      } else {
        // Smooth bark with faint horizontal lenticels.
        const base = noise2(x / 8, y / 8, 21, w / 8, h / 8);
        const len = noise2(x / 10, y / 1.5, 22, w / 10, h / 1.5);
        v = 0.82 + 0.14 * base - (len > 0.82 ? 0.25 : 0);
      }
      const c = Math.round(Math.min(1, v) * 255);
      data.set([c, c, c, 255], (y * w + x) * 4);
    }
  t = new DataTexture(data, w, h);
  t.wrapS = t.wrapT = RepeatWrapping;
  t.magFilter = LinearFilter;
  t.minFilter = LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.colorSpace = SRGBColorSpace;
  t.needsUpdate = true;
  textures.set(`bark:${kind}`, t);
  return t;
}

/**
 * Leaf atlas (alpha = leaf mask, grey = shading, the vertex colour tints it). Left half: one cluster (needle spray
 * along v / leaves splayed from the bottom centre); right half: a dense patch of clusters (merged and crown cards).
 */
export function foliageTexture(kind: FoliageKind): Texture {
  let t = textures.get(`leaf:${kind}`);
  if (t) return t;
  const S = 128;
  const W = S * 2;
  const alpha = new Float32Array(W * S);
  const shade = new Float32Array(W * S).fill(1);
  const stamp = (cx: number, cy: number, r: number, v: number, x0: number) => {
    for (let y = Math.max(0, Math.floor(cy - r)); y <= Math.min(S - 1, Math.ceil(cy + r)); y++)
      for (let x = Math.max(0, Math.floor(cx - r)); x <= Math.min(S - 1, Math.ceil(cx + r)); x++) {
        const d = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
        const a = Math.min(1, Math.max(0, r - d + 0.5));
        const k = y * W + x0 + x;
        if (a > alpha[k]) {
          alpha[k] = a;
          shade[k] = v;
        }
      }
  };
  const line = (x0: number, y0: number, x1: number, y1: number, r: number, v0: number, v1: number, ox: number) => {
    const n = Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 0.5);
    for (let i = 0; i <= n; i++) {
      const f = i / n;
      stamp(x0 + (x1 - x0) * f, y0 + (y1 - y0) * f, r, v0 + (v1 - v0) * f, ox);
    }
  };
  const leaf = (cx: number, cy: number, ang: number, l: number, wd: number, v: number, ox: number) => {
    // An ellipse along `ang` from (cx, cy), lighter at the tip, with a darker midrib.
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    const n = Math.ceil(l / 0.7);
    for (let i = 0; i <= n; i++) {
      const f = i / n;
      const r = wd * Math.sin(Math.PI * Math.min(1, f * 1.05 + 0.02));
      stamp(cx + dx * l * f, cy + dy * l * f, Math.max(0.6, r), v * (0.85 + 0.25 * f), ox);
    }
    line(cx, cy, cx + dx * l * 0.9, cy + dy * l * 0.9, 0.5, v * 0.7, v * 0.8, ox);
  };
  const spray = (ox: number, cx: number, cy: number, len: number, ang: number, seed: number) => {
    // A twig with needles both sides, angled forward.
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    line(cx, cy, cx + dx * len, cy + dy * len, 0.9, 0.55, 0.6, ox);
    for (let i = 0; i < len / 2.2; i++) {
      const f = (i * 2.2) / len;
      const px = cx + dx * len * f;
      const py = cy + dy * len * f;
      for (const side of [-1, 1]) {
        const a = ang + side * (0.75 + 0.2 * unit(mix32(seed, i * 2 + (side > 0 ? 1 : 0))));
        const nl = len * 0.22 * (1 - f * 0.5);
        line(px, py, px + Math.cos(a) * nl, py + Math.sin(a) * nl, 0.55, 0.7, 1.05, ox);
      }
    }
  };
  const blob = (ox: number, seed: number) => {
    // Dense patch: many small clusters inside a rough round outline.
    for (let i = 0; i < 260; i++) {
      const a = unit(mix32(seed, i * 3)) * Math.PI * 2;
      const r = Math.sqrt(unit(mix32(seed, i * 3 + 1))) * S * 0.44;
      const cx = S / 2 + Math.cos(a) * r;
      const cy = S / 2 + Math.sin(a) * r * 0.92;
      const v = 0.65 + 0.45 * unit(mix32(seed, i * 3 + 2)) * (0.6 + 0.4 * (cy / S));
      if (kind === 'needles') spray(ox, cx, cy, 12, a + 1.2, seed + i);
      else leaf(cx, cy, a + 2.2, 10, 3.6, v, ox);
    }
  };
  if (kind === 'needles') {
    // Spray along v (the card runs along the twig, tip at v = 1).
    line(S / 2, 2, S / 2, S - 4, 1.4, 0.5, 0.6, 0);
    for (let i = 0; i < 26; i++) {
      const y = 6 + i * 4.6;
      for (const side of [-1, 1]) {
        const a = Math.PI / 2 + side * (0.85 + 0.25 * unit(mix32(7, i * 2 + side)));
        const l = 40 * (1 - (i / 26) * 0.45);
        line(S / 2, y, S / 2 + Math.cos(a) * l, y + Math.sin(a) * l, 0.75, 0.6, 1.08, 0);
      }
    }
  } else {
    // Leaves splayed from the bottom centre (the twig tip) up and out.
    for (let i = 0; i < 7; i++) {
      const a = Math.PI / 2 + (i - 3) * 0.32 + 0.08 * unit(mix32(5, i));
      const l = 52 + 18 * unit(mix32(6, i));
      leaf(S / 2 + (i - 3) * 2, 6 + Math.abs(i - 3) * 6, a, l, 15, 0.8 + 0.25 * unit(mix32(9, i)), 0);
    }
  }
  blob(S, kind === 'needles' ? 31 : 41);
  const data = new Uint8Array(W * S * 4);
  for (let k = 0; k < W * S; k++) {
    const c = Math.round(Math.min(1, shade[k]) * 255);
    data.set([c, c, c, Math.round(alpha[k] * 255)], k * 4);
  }
  t = new DataTexture(data, W, S);
  t.magFilter = LinearFilter;
  t.minFilter = LinearMipmapLinearFilter;
  t.generateMipmaps = true;
  t.colorSpace = SRGBColorSpace;
  t.needsUpdate = true;
  textures.set(`leaf:${kind}`, t);
  return t;
}

// --- materials -------------------------------------------------------------------------------------------------

const materials = new Map<string, MeshStandardMaterial | MeshDepthMaterial>();
let foliageA2C = false;

/** Alpha-to-coverage on the leaf cards when the renderer has MSAA (engine/materials.ts `setFoliageAntialias`). */
export function setTreeFoliageAntialias(on: boolean): void {
  foliageA2C = on;
  for (const [k, m] of materials)
    if (k.startsWith('leaf:') && m.alphaToCoverage !== on) {
      m.alphaToCoverage = on;
      m.needsUpdate = true;
    }
}

export function barkMaterial(kind: BarkTexture): MeshStandardMaterial {
  const key = `bark:${kind}`;
  let m = materials.get(key) as MeshStandardMaterial | undefined;
  if (m) return m;
  m = new MeshStandardMaterial({ vertexColors: true, map: barkTexture(kind), roughness: 0.95 });
  m.name = `tree ${key}`;
  hookStandard(m, 'tree-bark-v1', false);
  materials.set(key, m);
  return m;
}

export function foliageMaterial(kind: FoliageKind): MeshStandardMaterial {
  const key = `leaf:${kind}`;
  let m = materials.get(key) as MeshStandardMaterial | undefined;
  if (m) return m;
  m = new MeshStandardMaterial({
    vertexColors: true,
    map: foliageTexture(kind),
    alphaTest: 0.5,
    side: DoubleSide,
    roughness: 0.85,
  });
  m.name = `tree ${key}`;
  m.alphaToCoverage = foliageA2C;
  m.defines = { TREE_LEAF: 1, RALLY_FOLIAGE: 0.45 };
  hookStandard(m, 'tree-leaf-v1', true);
  materials.set(key, m);
  return m;
}

/** Shadow-pass material of tree meshes: wind, the shadow level fade and (leaves) the alpha test three copies over. */
export function treeDepthMaterial(leaf: boolean): MeshDepthMaterial {
  const key = `depth:${leaf}`;
  let m = materials.get(key) as MeshDepthMaterial | undefined;
  if (m) return m;
  m = new MeshDepthMaterial({ depthPacking: RGBADepthPacking });
  m.defines = { TREE_SHADOW_PASS: 1, ...(leaf ? { TREE_LEAF: 1 } : {}) };
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    Object.assign(shader.uniforms, treeUniforms);
    injectVertex(shader, true);
    injectFragment(shader);
  };
  m.customProgramCacheKey = () => `tree-depth-v1-${leaf}`;
  materials.set(key, m);
  return m;
}

// --- impostor --------------------------------------------------------------------------------------------------

/** Octahedral impostor atlas: N x N frames over the upper hemisphere (trees/impostor.ts bakes them). */
export const IMPOSTOR_FRAMES = 8;

/** Hemi-octahedral map of a unit direction with y >= 0 -> [0, 1]^2 (the same formula as the shader). */
export function hemiOctEncode(d: [number, number, number]): [number, number] {
  const s = Math.abs(d[0]) + Math.abs(d[2]) + Math.max(d[1], 0);
  const px = d[0] / s;
  const pz = d[2] / s;
  return [(px + pz) * 0.5 + 0.5, (px - pz) * 0.5 + 0.5];
}

export function hemiOctDecode(u: number, v: number): [number, number, number] {
  const fx = u * 2 - 1;
  const fy = v * 2 - 1;
  const x = (fx + fy) * 0.5;
  const z = (fx - fy) * 0.5;
  const y = 1 - Math.abs(x) - Math.abs(z);
  const l = Math.sqrt(x * x + y * y + z * z);
  return [x / l, y / l, z / l];
}

const IMPOSTOR_VERTEX = /* glsl */ `
	// Billboard around the bounding sphere centre, facing the camera, upright like the bake cameras.
	vec3 tiCenter = tOrigin + vec3( 0.0, tlSphere.x * tScale, 0.0 );
	vec3 tiToCam = normalize( cameraPosition - tiCenter );
	vec3 tiRight = cross( vec3( 0.0, 1.0, 0.0 ), tiToCam );
	tiRight = dot( tiRight, tiRight ) > 1e-6 ? normalize( tiRight ) : tRot * vec3( 1.0, 0.0, 0.0 );
	vec3 tiUp = cross( tiToCam, tiRight );
	float tiR = tlSphere.y * tScale;
	vec3 tiWorld = tiCenter + ( tiRight * position.x + tiUp * position.y ) * tiR;
	// Trunk sway at this corner's height above the foot (object space), the same as the geometry levels.
	tiWorld += tWindW * treeTrunk( ( tiWorld.y - tOrigin.y ) / tScale, treeInst.z, tGust ) * tScale;
	vec4 mvPosition = viewMatrix * vec4( tiWorld, 1.0 );
	gl_Position = projectionMatrix * mvPosition;
	// Frames: the 4 grid directions around the object-space view direction, bilinear weights.
	vec3 tiDir = transpose( tRot ) * tiToCam;
	tiDir.y = max( tiDir.y, 0.0 );
	float tiS = abs( tiDir.x ) + abs( tiDir.z ) + tiDir.y;
	vec2 tiP = tiDir.xz / tiS;
	vec2 tiGrid = ( vec2( tiP.x + tiP.y, tiP.x - tiP.y ) * 0.5 + 0.5 ) * ( TREE_FRAMES - 1.0 );
	vec2 tiF0 = min( floor( tiGrid ), vec2( TREE_FRAMES - 2.0 ) );
	vTiFrame = tiF0;
	vTiWeight = tiGrid - tiF0;
	vTiUv = position.xy * 0.5 + 0.5;
	vTiRot0 = tRot[ 0 ];
	vTiRot1 = tRot[ 1 ];
	vTiRot2 = tRot[ 2 ];
	vTiDepth = tiR;
	vTiToCamView = normalize( ( viewMatrix * vec4( tiToCam, 0.0 ) ).xyz );
`;

const IMPOSTOR_FRAGMENT = /* glsl */ `
	vec4 tiAlbedo = vec4( 0.0 );
	vec4 tiNormal = vec4( 0.0 );
	for ( int k = 0; k < 4; k ++ ) {
		vec2 off = vec2( float( k % 2 ), float( k / 2 ) );
		float w = mix( 1.0 - vTiWeight.x, vTiWeight.x, off.x ) * mix( 1.0 - vTiWeight.y, vTiWeight.y, off.y );
		vec2 uvA = ( vTiFrame + off + clamp( vTiUv, 0.002, 0.998 ) ) / TREE_FRAMES;
		tiAlbedo += texture2D( tlAlbedo, uvA ) * w;
		tiNormal += texture2D( tlNormal, uvA ) * w;
	}
	if ( tiAlbedo.a < 0.5 ) discard;
	diffuseColor.rgb = tiAlbedo.rgb / max( tiAlbedo.a, 1e-3 );
	diffuseColor.a = 1.0;
`;

/** Per-variant impostor material: its two atlases (albedo + coverage, object-space normal + depth). */
export function impostorMaterial(
  albedo: Texture,
  normal: Texture,
  sphere: { cy: number; r: number },
): MeshStandardMaterial {
  const m = new MeshStandardMaterial({ roughness: 0.9 });
  m.name = 'tree impostor';
  m.defines = { TREE_IMPOSTOR: 1, TREE_FRAMES: `${IMPOSTOR_FRAMES}.0`, RALLY_FOLIAGE: 0.45 };
  const uniforms = {
    tlAlbedo: { value: albedo },
    tlNormal: { value: normal },
    tlSphere: { value: new Vector2(sphere.cy, sphere.r) },
  };
  m.onBeforeCompile = (shader) => {
    addWorldUniforms(shader);
    Object.assign(shader.uniforms, treeUniforms, uniforms);
    const vary = /* glsl */ `
varying vec2 vTiFrame;
varying vec2 vTiWeight;
varying vec2 vTiUv;
varying vec3 vTiRot0;
varying vec3 vTiRot1;
varying vec3 vTiRot2;
varying float vTiDepth;
varying vec3 vTiToCamView;
`;
    injectVertex(shader, false);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>\nuniform vec2 tlSphere;\n${vary}`)
      .replace('#include <project_vertex>', `${IMPOSTOR_VERTEX}\n${VERTEX_COLLAPSE}`);
    injectFragment(shader);
    shader.fragmentShader = shader.fragmentShader
      .replace(
        '#include <common>',
        `#include <common>\nuniform sampler2D tlAlbedo;\nuniform sampler2D tlNormal;\nuniform mat4 projectionMatrix;\n${vary}`,
      )
      .replace('#include <map_fragment>', `#include <map_fragment>\n${IMPOSTOR_FRAGMENT}\n${FRAGMENT_COLOR}`)
      .replace(
        '#include <normal_fragment_begin>',
        `#include <normal_fragment_begin>
	vec3 tiN = mat3( vTiRot0, vTiRot1, vTiRot2 ) * ( tiNormal.xyz / max( tiAlbedo.a, 1e-3 ) * 2.0 - 1.0 );
	normal = normalize( ( viewMatrix * vec4( tiN, 0.0 ) ).xyz );
	nonPerturbedNormal = normal;
	// Depth: the baked surface sits this far in front of / behind the billboard plane.
	vec3 tiView = - vViewPosition + vTiToCamView * ( ( tiNormal.w / max( tiAlbedo.a, 1e-3 ) ) * 2.0 - 1.0 ) * vTiDepth;
	vec4 tiClip = projectionMatrix * vec4( tiView, 1.0 );
	gl_FragDepth = clamp( tiClip.z / tiClip.w * 0.5 + 0.5, 0.0, 1.0 );`,
      );
  };
  m.customProgramCacheKey = () => 'tree-impostor-v2';
  return m;
}

