import {
  BufferAttribute,
  BufferGeometry,
  type MeshStandardMaterial,
  type Texture,
  type WebGLRenderer,
} from 'three';
import { getCached, pruneCached, putCached } from './cache';
import { bakeImpostor, impostorTextures, type ImpostorPixels } from './impostor';
import {
  barkMaterial,
  barkTexture,
  foliageMaterial,
  foliageTexture,
  impostorMaterial,
} from './materials';
import type { MeshData, VariantMeshes } from './mesh';
import { getSpecies, isTreeType, speciesOfType, type SpeciesDef } from './species';
import {
  cacheKey,
  generateVariant,
  registerVariant,
  variantSeed,
  variantsOf,
  type GeneratedVariant,
  type TreeVariantInfo,
} from './variants';
import type { GenerateRequest } from './worker';

/**
 * Stage load (spec: trees/Grammar.md#timing, trees/Placement.md#caching): every variant of the species a map uses,
 * from the disk cache or generated in a worker (never during a frame), turned into shared GPU geometry, its
 * impostor baked, and its summary registered for placement. `TreeLibrary` is what the drawing stage reads.
 */

export interface LoadedVariant {
  info: TreeVariantInfo;
  def: SpeciesDef;
  /** LOD0..2: bark tubes and foliage cards. */
  levels: { bark: BufferGeometry; foliage: BufferGeometry }[];
  impostor: { albedo: Texture; normal: Texture; material: MeshStandardMaterial };
}

function geometry(m: MeshData): BufferGeometry {
  const g = new BufferGeometry();
  g.setAttribute('position', new BufferAttribute(m.position, 3));
  g.setAttribute('normal', new BufferAttribute(m.normal, 3));
  g.setAttribute('uv', new BufferAttribute(m.uv, 2));
  g.setAttribute('color', new BufferAttribute(m.color, 3));
  g.setAttribute('treeWind', new BufferAttribute(m.wind, 4));
  g.setIndex(new BufferAttribute(m.index, 1));
  g.computeBoundingSphere();
  return g;
}

/** Generates variants in a worker (or inline where there are no workers). */
class Generator {
  private worker: Worker | null = null;
  private pending = new Map<number, (g: GeneratedVariant) => void>();
  private next = 0;

  constructor() {
    if (typeof Worker === 'undefined') return;
    try {
      this.worker = new Worker(new URL('./worker.ts', import.meta.url), { type: 'module' });
      this.worker.onmessage = (e: MessageEvent<GeneratedVariant & { id: number }>) => {
        const done = this.pending.get(e.data.id);
        this.pending.delete(e.data.id);
        done?.(e.data);
      };
    } catch {
      this.worker = null;
    }
  }

  generate(def: SpeciesDef, index: number): Promise<GeneratedVariant> {
    if (!this.worker) return Promise.resolve(generateVariant(def, index));
    const id = this.next++;
    return new Promise((resolve) => {
      this.pending.set(id, resolve);
      const req: GenerateRequest = { id, species: def.name, index };
      this.worker!.postMessage(req);
    });
  }

  dispose(): void {
    this.worker?.terminate();
  }
}

export class TreeLibrary {
  private variants = new Map<string, LoadedVariant[]>();

  /** Species of every tree type in `assets` (map rules / fixed instances). */
  static speciesOf(assets: Iterable<string>): SpeciesDef[] {
    const out = new Set<SpeciesDef>();
    for (const a of assets) if (isTreeType(a)) out.add(speciesOfType(a));
    return [...out];
  }

  /** Load every variant of `species`; `report` gets 0..1 progress. */
  static async load(
    species: SpeciesDef[],
    renderer: WebGLRenderer,
    report: (f: number) => void = () => {},
  ): Promise<TreeLibrary> {
    const lib = new TreeLibrary();
    const gen = new Generator();
    const jobs = species.flatMap((def) => variantsOf(def).map((i) => ({ def, i })));
    let done = 0;
    // Cache lookups / worker generation run in parallel; baking (GPU) one after another as results arrive.
    const results = await Promise.all(
      jobs.map(async ({ def, i }) => {
        const key = cacheKey(def, variantSeed(def, i));
        const cached = await getCached(key);
        const g = cached ?? (await gen.generate(def, i));
        return { def, i, key, g, impostor: cached?.impostor };
      }),
    );
    gen.dispose();
    for (const { def, i, key, g, impostor } of results) {
      const v = lib.build(def, g.info, g.meshes, impostor, renderer);
      if (!impostor) void putCached(key, { info: g.info, meshes: g.meshes, impostor: v.pixels });
      let list = lib.variants.get(def.name);
      if (!list) lib.variants.set(def.name, (list = []));
      list[i] = v.loaded;
      report(++done / jobs.length);
    }
    for (const def of species)
      void pruneCached(def.name, new Set(variantsOf(def).map((i) => cacheKey(def, variantSeed(def, i)))));
    return lib;
  }

  private build(
    def: SpeciesDef,
    info: TreeVariantInfo,
    meshes: VariantMeshes,
    cachedImpostor: ImpostorPixels | undefined,
    renderer: WebGLRenderer,
  ): { loaded: LoadedVariant; pixels: ImpostorPixels } {
    registerVariant(info);
    const levels = meshes.levels.map((l) => ({ bark: geometry(l.bark), foliage: geometry(l.foliage) }));
    const pixels =
      cachedImpostor ??
      bakeImpostor(
        renderer,
        [
          { geometry: levels[0].bark, map: barkTexture(def.bark.texture), leaf: false },
          { geometry: levels[0].foliage, map: foliageTexture(def.foliage.kind), leaf: true },
        ],
        info.sphere,
      );
    const tex = impostorTextures(pixels);
    // Materials are shared per bark / leaf kind; created here so they exist before the first frame.
    barkMaterial(def.bark.texture);
    foliageMaterial(def.foliage.kind);
    return {
      loaded: {
        info,
        def,
        levels,
        impostor: { ...tex, material: impostorMaterial(tex.albedo, tex.normal, info.sphere) },
      },
      pixels,
    };
  }

  get species(): string[] {
    return [...this.variants.keys()];
  }

  variant(species: string, index: number): LoadedVariant | undefined {
    return this.variants.get(species)?.[index];
  }

  all(): LoadedVariant[] {
    return [...this.variants.values()].flat();
  }

  dispose(): void {
    for (const v of this.all()) {
      for (const l of v.levels) {
        l.bark.dispose();
        l.foliage.dispose();
      }
      v.impostor.albedo.dispose();
      v.impostor.normal.dispose();
      v.impostor.material.dispose();
    }
    this.variants.clear();
  }
}

export { getSpecies };

