cat > .shots/tree.js <<'EOF'
(() => {
  const v = __mapViewer;
  const want = window.__species;
  const dist = window.__dist ?? 14;
  const cs = v.world.scatter.chunkSize;
  const p = v.world.road.at(window.__along ?? 1500);
  let best = null;
  for (let dz = -3; dz <= 3; dz++) for (let dx = -3; dx <= 3; dx++) {
    const ch = v.world.scatter.chunk(Math.floor(p.x / cs) + dx, Math.floor(p.z / cs) + dz);
    for (const i of ch.instances) if (i.tree && i.tree.species === want) {
      const d = Math.hypot(i.x - p.x, i.z - p.z);
      if (!best || d < best.d) best = { i, d };
    }
  }
  if (!best) return 'none';
  const t = best.i;
  const h = t.scale * 9;
  const cx = t.x + dist, cz = t.z + dist * 0.4;
  const cy = v.world.analytic.height(cx, cz) + 1.6;
  v.look(cx, cy, cz, t.x, t.y + (window.__aim ?? h * 0.45), t.z, window.__fov ?? 50);
  return { at: [t.x, t.y, t.z], variant: t.variant, scale: t.scale, drawn: v.trees.drawn };
})()
EOF
